  [94369] = { nil, "Parla con Talaanis Shadowsong a Valanaar.", nil, nil, nil, nil, 0x4440ff8a, nil, nil, nil, "m.mmm" },
  [94373] = { "Il richiamo della terra", "Porta 2 Frostmane Bear Pendant a Teo Hammerstorm a ⟦Anvilmar=Forgiamara⟧.", "Sì, è giunto il momento, giovane <sciamano/sciamana>. Sei cresciut<o/a> robust<o/a> e solid<o/a>, come la pietra sotto i nostri stivali. Intraprendere il sentiero dello sciamano dimostra che hai la saggezza della montagna, ancor prima di aver dato prova di te. Hai la tempra della pietra per percorrere il sentiero della terra.\n\nMa per guadagnarti il suo favore devi affrontarla come si deve. A sud di qui, i troll ⟦Frostmane=Mantogelido⟧ vivono in una grotta.\n\nPortami due delle collane che indossano, fatte con gli orsi Iceclaw. Poi parleremo ancora del tuo futuro.", "La pazienza, <ragazzo/ragazza>, è la virtù più bella della terra. Ha visto montagne sgretolarsi e fiumi scavare valli: lenta e testarda, come un vero {race}. Ora la terra ti chiama, perché all'orizzonte si prepara qualche guaio. Torna con un successo e sarai un passo più vicin<o/a> a essere complet<o/a>.\n\nAltri potranno invidiare la tua saggezza, ma quello è un fardello che tocca a loro portare.", "Ben fatto, <ragazzo/ragazza>. Hai dimostrato di essere <pronto/pronta>. La terra è il fondamento di tutte le cose. Forza, resistenza, pazienza. Ti farà da scudo, ma solo se le porterai il rispetto che merita. Anche la pietra può muoversi se viene offesa. Impara le sue vie e diventerai più saggi<o/a> della maggior parte della gente. Non dimenticare mai i segreti che condivide.\n\nOra ti preparerò un sapta: accettalo e percorrerai il vero sentiero.", 0xe316c17f, 0xc897beee, 0x70173b78, 0xd804d26a, 0xb1f39df1, "....." },
  [94374] = { "Il richiamo della terra", "Trova la Spirit Stone e bevi il ⟦Earth Sapta=Sapta di Terra⟧.", "Sì, il sapta è un intruglio forgiato con la magia, che lega il nostro spirito agli elementi. Solo pochi sciamani ne conoscono la ricetta, e non è roba per chi ha la volontà debole. Bevilo e vedrai ciò che gli altri non possono vedere. Ricorda bene: va bevuto solo in un luogo sacro.\n\nDirigiti a nord verso la Spirit Stone, nascosta in fondo a un sentiero segreto su per la montagna. Bevilo lì... e guarda cosa ha da mostrarti la terra.", nil, "Ah... {name}... la terra ti accoglie, anche in questa terra gelata. Unit<o/a> nel corpo e nello spirito, andrai avanti sapendo che le montagne sono la tua forza, le pianure la tua pazienza e il mondo la tua essenza.\n\nPer superare questo rito, presentati con umiltà davanti alla terra. Gli altri elementi non sono così quieti: si scontrano e ruggiscono. Impara la loro duplice natura, anche qui tra la neve e la pietra.", 0xe316c17f, 0x4c31146f, 0x28284db1, nil, 0xcd853d2f, "...m." },
  [94375] = { "Il richiamo della terra", "Porta il ⟦Rough Quartz=Quarzo Grezzo⟧ a Teo Hammerstorm a ⟦Anvilmar=Forgiamara⟧.", "Prendi da me questo quarzo grezzo e portalo a Teo Hammerstorm come prova del nostro incontro. Creerà un totem per te, e questo sassolino ne sarà il cuore. Per quanto possa sembrare piccolo, scoprirai che la grandezza non conta, e che anche le cose più piccole possono durare più di molte altre.\n\nSii paziente, {name}. Resta saldo nello spirito. E cerca la saggezza. Questo è ciò che la terra ti chiede. Alla fine diventerai una cosa sola con la terra: rispettala, come lei rispetterà te.", "Ahh, sei tornat<o/a>. Se hai la pietra, vuol dire che la montagna ti ha scelt<o/a> davvero. Ti darò il totem che ti ha promesso. Ma se sei venut<o/a> a mani vuote, fuori dai piedi! Il sentiero non è per chi dimentica la propria strada.", nil, 0xe316c17f, 0x1c898e3e, 0x1415c33d, 0xa9c8dad9, nil, "....m" },
  [94449] = { "Il richiamo del fuoco", "Trova Bruegs Kindleborn a Dun Morogh.", "È passato molto dall'ultima volta che sei stat<o/a> mess<o/a> alla prova, {name}. Hai dimostrato pazienza, sì, ma ora è tempo che tu impari il caos... la distruzione. Il richiamo del fuoco è forte, e se sei <pronto/pronta> a pagarne il prezzo, ti parlerà.\n\nCerca Bruegs Kindleborn, lontano a est tra le montagne. Vive in una grotta sopra l'⟦South Gate Outpost=Avamposto Meridionale⟧. Lui saprà se sei davvero <pronto/pronta>.", nil, nil, 0x53f3b76b, 0x15200cd4, 0xf3c2198f, nil, nil, "...mm" },
  [94465] = { "Il richiamo del fuoco", "Porta la ⟦Torch of the Dormant Flame=Torcia della Fiamma Sopita⟧ a Braldir Ashmantle a Loch Modan.", "Sì, hai la forza per portare il totem del fuoco, <ragazzo/ragazza>, ma la forza da sola non basta a renderti <pronto/pronta>.\n\nOltre la Valley of Kings, tra le rupi di Loch Modan, c'è un sentiero nascosto che porta a una delle nostre vette sacre. Lì Braldir Ashmantle custodisce lo Shrine of the Dormant Flame.\n\nPortagli questa torcia: dimostra le tue intenzioni. Riportala accesa dal braciere del santuario e farò in modo che tu ti guadagni il totem come si deve.", nil, nil, 0x53f3b76b, 0xef8da8e8, 0x415200cc, nil, nil, "...mm" },
  [94466] = { "Il richiamo del fuoco", "Porta 1 ⟦Fire Tar=Catrame di Fuoco⟧ e 1 ⟦Reagent Pouch=Borsa dei Reagenti⟧ a Braldir Ashmantle a Loch Modan.", "Bah, non avrai fatto tutta questa strada per sentire storie, eh, {name}? Cerchi la Fiamma Eterna e il totem del fuoco.\n\nPrima di tutto, ti servirà un sapta per legare il tuo spirito alla fiamma.\n\nTe lo preparerò io, ma mi servono due cose: catrame di fuoco dai Tunnel Rat Geomancer nelle grotte dei kobold a nord, e una borsa dei reagenti da uno Stonesplinter Seer che si aggira sulle colline a sud. Un lavoro pericoloso, ma degno della fiamma.", nil, nil, 0x53f3b76b, 0x1ec23f46, 0x08842bb0, nil, nil, "...mm" },
  [94467] = { "Il richiamo del fuoco", "Sconfiggi la Minor Manifestation of Fire e metti la ⟦Glowing Ember=Brace Luminosa⟧ nel braciere in cima allo Shrine of Eternal Flame.", "Il sapta di fuoco è pronto, {name}. Ora affronterai la fiamma. Usalo al santuario, poi sali sulla vetta. Lì vedrai lo spirito: non attaccherà finché non lo farai tu, ma saprà che lo vedi.\n\nColpisci in fretta, <ragazzo/ragazza>. Più aspetti, più arde forte. Quando cade, prendi le sue braci luminose e mettile nel braciere. Accendi la torcia e guadagnati il favore del fuoco.", nil, nil, 0x53f3b76b, 0x7d09c623, 0xbfb4503b, nil, nil, "...mm" },
  [94468] = { "Il richiamo del fuoco", "Porta la Torch of Eternal Flame a Bruegs Kindleborn a Dun Morogh.", "Con la torcia ben stretta in mano, ti allontani dal braciere e guardi Loch Modan dall'alto. Senti un'eccitazione che ti scuote lo spirito mentre il vento si alza e costringe la fiamma a danzare violentemente.\n\nTi incammini lungo il sentiero che riporta a Dun Morogh, in cerca di Bruegs Kindleborn.", nil, nil, 0x53f3b76b, 0x8fb8c297, 0x74b18970, nil, nil, "...mm" },
  [94472] = { "⟦Earth Sapta=Sapta di Terra⟧", "Parla con Teo Hammerstorm per avere un altro ⟦Earth Sapta=Sapta di Terra⟧.", nil, nil, "Prendi questa e ricorda: è sacra.", 0x9c7e1740, 0x0b15db68, nil, nil, 0x794bb81e, "..mm." },
  [94473] = { "⟦Fire Sapta=Sapta di Fuoco⟧", "Parla con Braldir Ashmantle per avere un altro ⟦Fire Sapta=Sapta di Fuoco⟧.", nil, nil, nil, 0xe8738c8b, 0x60e76b9e, nil, nil, nil, "..mmm" },
  [94494] = { "Il richiamo dell'acqua", "Trova Norric Lochthane a Loch Modan.", "È passato molto tempo dall'ultima volta che sei stat<o/a> mess<o/a> alla prova, {name}. Finora hai mostrato pazienza nei tuoi studi, ma è giunto il momento che tu impari la purezza dell'acqua.\n\nCerca Norric Lochthane a Loch Modan. Si trova lungo la sponda nord-occidentale del lago, a sud della ⟦Stonewrought Dam=Diga di Pietrasalda⟧. Lo troverai lì, nella sua casupola. Buona fortuna, {name}.", nil, nil, 0x1f0e11aa, 0xa614e79c, 0xf11bb23d, nil, nil, "...mm" },
  [94495] = { "Il richiamo dell'acqua", "Trova Hervdana Saegrund nelle ⟦Wetlands=Paludi Grigie⟧.", "Se c'è una verità che devi imparare sull'acqua, è questa: l'acqua significa rinascita. Scava la pietra, lava la sporcizia e guarisce gli stanchi, ma solo quando è pura. Contaminala e rovinerà tutto ciò che tocca.\n\nSe cerchi il sapta d'acqua, trova Hervdana Saegrund nelle ⟦Wetlands=Paludi Grigie⟧. La sua famiglia vive in una grotta sotto le cascate meridionali.\n\nSu, vai, non lasciare che il fiume corra più veloce di te.", nil, nil, 0x1f0e11aa, 0xadc7f213, 0xadd95e2e, nil, nil, "...mm" },
  [94497] = { "Il richiamo dell'acqua", "Riempi la ⟦Empty Brown Waterskin=Borraccia Marrone Vuota⟧ ai piedi delle cascate sotto la grotta di Hervdana e riportagliela nelle ⟦Wetlands=Paludi Grigie⟧.", "Ah, quindi sei venut<o/a> a cercare il sapta, eh? Be', allora ascolta bene, <caro/cara>. Per trovare la comprensione e guadagnarti il sapta, devi cercare l'acqua nelle sue varie forme. Mentre raccogli i campioni, tieni gli occhi aperti. Osserva le bestie che la custodiscono, la terra che nutre e come cambia le vite.\n\nCominciamo con qualcosa di semplice: riempi questa borraccia ai piedi delle cascate, dove l'acqua dolce incontra quella salmastra. Su, vai, e attent<o/a> alla palude.", nil, nil, 0x1f0e11aa, 0xa3d8f378, 0x4ed51e9b, nil, nil, "...mm" },
  [94499] = { "Il richiamo dell'acqua", "Riempi la ⟦Empty Red Waterskin=Borraccia Rossa Vuota⟧ alle ⟦Stonewatch Falls=Cascate di Guardamasso⟧, vicino ai Nightcrawler Murloc, e torna da Hervdana Saegrund nelle ⟦Wetlands=Paludi Grigie⟧.", "Sì, ⟦Redridge=Crestarossa⟧ beve a piene mani dal ⟦Lake Everstill=Lago Placido⟧, ma quando le acque precipitano giù per le ⟦Stonewatch Falls=Cascate di Guardamasso⟧, qualcosa ci si è infiltrato. I murloc laggiù sono bestioni grossi e deformi. Non come quelli che trovi qui o al Loch. Per fortuna dei paesani, restano ai piedi delle cascate.\n\nPortami un campione. Ho intenzione di scoprire se è magia, veleno o qualcosa di peggio a contaminare le acque vicino a quel vecchio forte.", nil, nil, 0x1f0e11aa, 0x6ccca7b4, 0xa2cb5a4a, nil, nil, "...mm" },
  [94500] = { "Il richiamo dell'acqua", "Riempi la Unfilled Blue Waterskin alle acque di Astranaar, a ⟦Ashenvale=Valtetra⟧, e torna da Hervdana Saegrund nelle ⟦Wetlands=Paludi Grigie⟧.", "Prendi questa borraccia e addentrati nell'ombra smeraldina di ⟦Ashenvale=Valtetra⟧. Astranaar riposa cullata da acque non toccate dalla corruzione. Il fondo del lago è disseminato di rovine, tracce di un'epoca passata. Riportami un campione dal lago. Acqua pura, antica e forse incantata.\n\nÈ l'ultimo liquido che mi serve prima di rimandarti da Norric.\n\nPrendi la nave da Menethil per Auberdine. Lungo il tragitto fa scalo a ⟦Southshore=Riva del Sud⟧.\n\nE sta' attent<o/a>... la foresta ha occhi, e non battono ciglio.", nil, nil, 0x1f0e11aa, 0x76aef756, 0xc7e05766, nil, nil, "...mm" },
  [94501] = { "Il richiamo dell'acqua", "Porta la ⟦Vial of Purest Water=Fiala d'Acqua Purissima⟧ a Norric Lochthane a Loch Modan.", "Norric avrà un ultimo compito per te prima di ricompensarti con i riti del totem dell'acqua. La fiala d'acqua che ti ho dato è necessaria per quel compito, qualunque esso sia. Ora va' a cercarlo. Un giorno ci rivedremo.", nil, nil, 0x1f0e11aa, 0x0d508544, 0x58506c33, nil, nil, "...mm" },
  [94502] = { "Il richiamo dell'acqua", "Bevi il ⟦Water Sapta=Sapta d'Acqua⟧ e purifica la corruzione allo ⟦Stendel's Pond=Stagno di Stendel⟧, nelle ⟦Westfall=Marche Occidentali⟧.\nQuando hai finito, torna da Norric a Loch Modan.", "Nelle ⟦Westfall=Marche Occidentali⟧, fuori da ⟦Moonbrook=Rivoluna⟧, si trova lo ⟦Stendel's Pond=Stagno di Stendel⟧. Un tempo era una sorgente pura, ora è stata toccata da forze oscure. Gli spiriti di quel luogo sono ammutoliti.\n\nDevi bere il sapta d'acqua, poi affrontare la corruzione che insozza le acque. Prendi i suoi bracciali e le ultime gocce della pozione di Hervdana, poi mettili sul santuario. Questo richiamerà uno spirito, purificato e sincero. Parlagli, impara ciò che puoi.\n\nPortami la prova che il compito è svolto e ti concederò il totem.", nil, nil, 0x1f0e11aa, 0x3dec7b07, 0x1215dd1a, nil, nil, "...mm" },
  [94503] = { "Il richiamo dell'acqua", "Parla con la Minor Manifestation of Water nelle ⟦Westfall=Marche Occidentali⟧.", "Una luce erompe mentre l'ultima parola ti lascia le labbra. Il sibilo dell'acqua che si fa vapore svanisce nel silenzio e i tuoi sensi vacillano mentre gli spiriti corrotti intorno a te si dissolvono, la loro essenza dispersa come cenere nel vento.", nil, nil, 0x1f0e11aa, 0x2cab5030, 0x31813519, nil, nil, "...mm" },
  [94505] = { "Il richiamo dell'acqua", "Porta la ⟦Shard of Water=Scheggia d'Acqua⟧ a Norric Lochthane a Loch Modan.", "Prendi scheggia. Prendi scheggia e dai vita.\n\nDai vita e comprendi. Comprendi che acqua è vita... corruzione ferma vita.\n\nTu proteggi e dai vita con potere dell'acqua.", nil, nil, 0x1f0e11aa, 0x038a8a5c, 0x1bc4c72c, nil, nil, "...mm" },
  [94616] = { "⟦Water Sapta=Sapta d'Acqua⟧", nil, nil, nil, nil, 0xcd2fb34a, nil, nil, nil, nil, ".mmmm" },
  [94773] = { "Grazia divina", nil, nil, nil, nil, 0x4199a5e1, nil, nil, nil, nil, ".mmmm" },
  [94774] = { "Grazia divina", "Parla con la somma sacerdotessa Laurena a ⟦Stormwind=Roccavento⟧.", "Hai attirato l'attenzione dei nostri superiori, {name}. Ti chiedono di recarti alla ⟦Cathedral of Light=Cattedrale della Luce⟧ a ⟦Stormwind=Roccavento⟧ il prima possibile. A quanto pare ritengono che tu abbia già dato prova di te e sono pronti a proseguire il tuo addestramento. Quando arrivi, cerca la somma sacerdotessa Laurena. Saprà guidarti oltre. Buona fortuna, e che la Luce sia con te.", nil, nil, 0x4199a5e1, 0x8de762b6, 0xb0903ab5, nil, nil, "...mm" },
  [94775] = { "Grazia divina", "Parla con la somma sacerdotessa Laurena a ⟦Stormwind=Roccavento⟧.", "Elune ti benedica, {race}. Spero che la tua Luce ti trovi e ti protegga bene in questo giorno.\n\nUno dei vostri sacerdoti è passato di qui non molto tempo fa a cercarti. Ha detto che dovresti tornare alla ⟦Cathedral of Light=Cattedrale della Luce⟧ il prima possibile per parlare con la somma sacerdotessa Laurena. Pare che tu abbia fatto bene, per attirare tanta attenzione. Non mi tratterrei troppo qui: la tua gente ha bisogno di te.", nil, nil, 0x4199a5e1, 0x8de762b6, 0x93d8c9e5, nil, nil, "...mm" },
  [94776] = { "Grazia divina", "Parla con la somma sacerdotessa Laurena a ⟦Stormwind=Roccavento⟧.", "È ora che tu vada a ⟦Stormwind=Roccavento⟧, {name}. La somma sacerdotessa Laurena, nella ⟦Cathedral of Light=Cattedrale della Luce⟧, vuole parlarti. Dev'essere qualcosa di molto buono o di molto brutto se la somma sacerdotessa ti vuole lì di persona, ma scommetto che hai solo fatto bene e che è una buona cosa che voglia parlarti.\n\nMa non perdere troppo tempo da queste parti. Io ci andrei il prima possibile.", nil, nil, 0x4199a5e1, 0x8de762b6, 0x0e82ce63, nil, nil, "...mm" },
  [94777] = { "Grazia divina", "Parla con la somma sacerdotessa Laurena a ⟦Stormwind=Roccavento⟧.", "Poco tempo fa uno dei vostri sacerdoti è passato di qui a cercarti, {race}. Ha detto che, se ti avessi vist<o/a>, avrei dovuto indirizzarti verso la ⟦Cathedral of Light=Cattedrale della Luce⟧. Ha detto che era molto importante, ma al tuo posto non mi preoccuperei troppo. Sembrava di buon umore... come se si trattasse di buone notizie. Al tuo posto non tarderei troppo ad andarci.\n\nElune sia con te, {race}.", nil, nil, 0x4199a5e1, 0x8de762b6, 0x1cfc2115, nil, nil, "...mm" },
  [94778] = { "Grazia divina", "Parla con la somma sacerdotessa Laurena a ⟦Stormwind=Roccavento⟧.", "C'è bisogno di te a ⟦Stormwind=Roccavento⟧, {name}. La somma sacerdotessa del posto, Laurena, dice che è giunto il momento di dimostrare che sei <degno/degna> del prossimo livello del tuo addestramento. Non perdere troppo tempo per arrivarci. La troverai nella ⟦Cathedral of Light=Cattedrale della Luce⟧, al centro della città. Portale i miei saluti e dimostra quanto sei <degno/degna> di una tale vocazione. La Luce sia con te, {name}.", nil, nil, 0x4199a5e1, 0x8de762b6, 0x8ea469d6, nil, nil, "...mm" },
  [94779] = { "Grazia divina", "Parla con la somma sacerdotessa Laurena a ⟦Stormwind=Roccavento⟧.", "Sia lodata Elune, e la tua Luce, {name}.\n\nPiù o meno in questo periodo, molti del nostro ordine apprendono abilità che riflettono la loro fede in Elune. Se non ricordo male, credo che lo stesso valga anche per il tuo ordine.\n\nQuando avrai concluso i tuoi affari a Darnassus, cercherei una delle vostre somme sacerdotesse per proseguire l'addestramento.", nil, nil, 0x4199a5e1, 0x8de762b6, 0x9d972e4f, nil, nil, "...mm" },
  [94789] = { "Il richiamo dell'aria", nil, nil, nil, nil, 0x8f4acf86, nil, nil, nil, nil, ".mmmm" },
  [94792] = { "Addomesticare la bestia", "Usa il ⟦Taming Rod=Bastone per Addomesticare⟧ per addomesticare un Rockhide Boar. Fai pratica, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a Josephine Carson.", "Molti cacciatori preferiscono viaggiare con compagni animali. Con una bestia al tuo fianco, scoprirai di poter sopravvivere anche nelle circostanze più pericolose. Come si dice, tutto è più facile con un amico. Tuttavia, procurarsi un compagno animale è qualcosa che va fatto con cura. L'equilibrio della natura è delicato e va sempre rispettato.\n\nPorta con te questo ⟦Taming Rod=Bastone per Addomesticare⟧ nella foresta. Con esso potrai addomesticare un Rockhide Boar e mettere in pratica le tue capacità di cacciatore.", "Imparerai, {name}, e un giorno sarai <un/una> grande {class}.", "Eccellente, {name}! Impari davvero in fretta.", 0xecd97a9a, 0x19efabbc, 0x69a91737, 0xe5057f89, 0x7f1a8496, "....." },
  [94793] = { "Addestrare la bestia", "Parla con Isaac Chan a ⟦Goldshire=Borgodoro⟧.", "Ora hai il potere di addomesticare un famiglio, ma devi anche acquisire le capacità per addestrarlo. Per questo non c'è nessuno migliore di Isaac Chan, un uomo dei boschi da una vita. Ti darà la capacità di addestrare il tuo nuovo famiglio.\n\nVa' con i venti, giovane {class}.", nil, "<Un/Una> {class} alle prime armi, vedo. Sì, posso darti le capacità che ti servono per addestrare e guidare il tuo famiglio. Non solo potrai insegnare al tuo famiglio nuove abilità, ma d'ora in poi potrai anche nutrirlo e riportarlo in vita, se dovesse cadere in battaglia.\n\nRicorda, {name}, rispetta sempre l'equilibrio e vivi con riverenza verso la natura che ti circonda. Ora va'. Ci parleremo di nuovo più avanti.", 0xdbeedc0e, 0xf8c4ebf2, 0x4bc880b0, nil, 0xfbd746d0, "...m." },
  [94817] = { "Lampo disorientante", nil, nil, nil, nil, 0xd8782324, nil, nil, nil, nil, ".mmmm" },
  [94819] = { nil, "Parla con la somma sacerdotessa Mims a ⟦Ironforge=Forgiardente⟧.", nil, nil, nil, nil, 0x656c5f67, nil, nil, nil, "m.mmm" },
  [94820] = { nil, "Parla con la somma sacerdotessa Mims a ⟦Ironforge=Forgiardente⟧.", nil, nil, nil, nil, 0x656c5f67, nil, nil, nil, "m.mmm" },
  [94821] = { "Lampo disorientante", "Parla con la somma sacerdotessa Mims a ⟦Ironforge=Forgiardente⟧.", nil, nil, nil, 0xd8782324, 0x656c5f67, nil, nil, nil, "..mmm" },
  [94822] = { "Lampo disorientante", "Parla con la somma sacerdotessa Mims a ⟦Ironforge=Forgiardente⟧.", nil, nil, nil, 0xd8782324, 0x656c5f67, nil, nil, nil, "..mmm" },
  [94823] = { "Lampo disorientante", "Parla con la somma sacerdotessa Mims a ⟦Ironforge=Forgiardente⟧.", nil, nil, nil, 0xd8782324, 0x656c5f67, nil, nil, nil, "..mmm" },
  [94824] = { "Lampo disorientante", "Parla con la somma sacerdotessa Mims a ⟦Ironforge=Forgiardente⟧.", nil, nil, nil, 0xd8782324, 0x656c5f67, nil, nil, nil, "..mmm" },
  [94825] = { "Lampo disorientante", "Parla con la somma sacerdotessa Mims a ⟦Ironforge=Forgiardente⟧.", "Poco fa uno dei vostri sacerdoti è venuto a cercarti, {race}. Ha detto che, se ti avessi visto, avrei dovuto indirizzarti verso la Hall of Mysteries. Ha detto che era molto importante, ma al tuo posto non mi preoccuperei troppo. Sembrava di buon umore... come se si trattasse di buone notizie. Al tuo posto, però, non tarderei ad andarci.\n\nChe Elune sia con te, nobile {race}.", nil, nil, 0xd8782324, 0x656c5f67, 0xa819c88b, nil, nil, "...mm" },
  [94826] = { "Lampo disorientante", "Parla con la somma sacerdotessa Mims a ⟦Ironforge=Forgiardente⟧.", nil, nil, nil, 0xd8782324, 0x656c5f67, nil, nil, nil, "..mmm" },
  [94863] = { "Addomesticare la bestia", nil, nil, nil, nil, 0xecd97a9a, nil, nil, nil, nil, ".mmmm" },
  [94864] = { "Addomesticare la bestia", nil, nil, nil, nil, 0xecd97a9a, nil, nil, nil, nil, ".mmmm" },
  [94872] = { "Comprare l'amicizia: Magram", "Porta il Totem Tote al quartiermastro dei Magram al Magram Village, a ⟦Desolace=Desolanda⟧, per accrescere notevolmente la tua reputazione presso quel clan. Devi essere almeno Neutrale con i ⟦Magram Clan Centaur=Centauri del Clan Magram⟧.", nil, nil, nil, 0xf5fd14ba, 0x66df78e4, nil, nil, nil, "..mmm" },
  [94873] = { "Comprare l'amicizia: Gelkis", "Porta il Totem Tote al quartiermastro dei Gelkis al ⟦Gelkis Village=Villaggio dei Gelkis⟧, a ⟦Desolace=Desolanda⟧, per accrescere notevolmente la tua reputazione presso quel clan. Devi essere almeno Neutrale con i ⟦Gelkis Clan Centaur=Centauri del Clan Gelkis⟧.", nil, nil, nil, 0x57c3db29, 0x68c32afb, nil, nil, nil, "..mmm" },
  [94913] = { "⟦Moonglade=Radaluna⟧", "Usa l'incantesimo \"⟦Teleport: Moonglade=Teletrasporto: Radaluna⟧\" per raggiungere ⟦Moonglade=Radaluna⟧. Al tuo arrivo, parla con Dendrite Starblaze nel villaggio di ⟦Nighthaven=Nottequieta⟧.", "Tutti i druidi sono i benvenuti nelle terre sacre di ⟦Moonglade=Radaluna⟧. Il custode Remulos, guardiano di ⟦Moonglade=Radaluna⟧, veglia su tutti i druidi che vi riposano. Ti insegnerò l'incantesimo che ti permette di trasportarti lì. Lancialo ogni volta che cerchi la conoscenza o il conforto di ⟦Moonglade=Radaluna⟧.\n\nQuanto alla tua prima lezione qui su Azeroth, recati a ⟦Moonglade=Radaluna⟧ e parla con Dendrite Starblaze a ⟦Nighthaven=Nottequieta⟧ del sentiero che ora percorri. Buona fortuna, giovane druido.", nil, "Ah, vedo che hai già padroneggiato la forma d'orso. Bene, bene. Sei sulla buona strada, giovane {class}.", 0xaeb97c8b, 0xf8085429, 0x89074bce, nil, 0x0e12a96b, "...m." },
  [94914] = { "⟦Moonglade=Radaluna⟧", "Usa l'incantesimo \"⟦Teleport: Moonglade=Teletrasporto: Radaluna⟧\" per raggiungere ⟦Moonglade=Radaluna⟧. Al tuo arrivo, parla con Dendrite Starblaze nel villaggio di ⟦Nighthaven=Nottequieta⟧.", "Tutti i druidi sono i benvenuti nelle terre sacre di ⟦Moonglade=Radaluna⟧. Il custode Remulos, guardiano di ⟦Moonglade=Radaluna⟧, veglia su tutti i druidi che vi riposano. Ti insegnerò l'incantesimo che ti permette di trasportarti lì. Lancialo ogni volta che cerchi la conoscenza o il conforto di ⟦Moonglade=Radaluna⟧.\n\nQuanto alla tua prima lezione qui su Azeroth, recati a ⟦Moonglade=Radaluna⟧ e parla con Dendrite Starblaze a ⟦Nighthaven=Nottequieta⟧ del sentiero che ora percorri. Buona fortuna, giovane druido.", nil, nil, 0xaeb97c8b, 0xf8085429, 0x89074bce, nil, nil, "...mm" },
  [94978] = { "Addomesticare la bestia", nil, nil, "Imparerai, {name}, e un giorno sarai <un/una> grande {class}.", nil, 0xecd97a9a, nil, nil, 0xe5057f89, nil, ".mm.m" },
  [94979] = { "Addomesticare la bestia", nil, nil, "Imparerai, {name}, e un giorno sarai <un/una> grande {class}.", nil, 0xecd97a9a, nil, nil, 0xe5057f89, nil, ".mm.m" },
})
